 private void text(Canvas c,String s,float x,float y,float size){paint.setStyle(Paint.Style.FILL);paint.setColor(theme.text);paint.setTypeface(theme.font(false));paint.setTextSize(size*Math.min(1.35f,getResources().getConfiguration().fontScale));paint.setTextAlign(Paint.Align.CENTER);c.drawText(s,x,y,paint);}
 private void panel(Canvas c,RectF r,int color){if(stage!=null){if(rules.game.kind==Kind.WATER&&r.height()>200)sceneNodes.add(new SceneFrame.Node(7,r.centerX(),r.centerY(),r.width(),r.height(),0,color,0,false));else sceneNodes.add(SceneFrame.panel(r.left,r.top,r.right,r.bottom,color));return;}paint.setStyle(Paint.Style.FILL);paint.setShader(new LinearGradient(0,r.top,0,r.bottom,color,theme.soft,Shader.TileMode.CLAMP));c.drawRoundRect(r,24,24,paint);paint.setShader(null);paint.setColor(theme.border);paint.setStrokeWidth(2);paint.setStyle(Paint.Style.STROKE);c.drawRoundRect(r,24,24,paint);paint.setStyle(Paint.Style.FILL);}
